package com.github.fmaiassistent.exporter;

import com.github.fmaiassistent.domain.NativeClubSnapshot;
import com.github.fmaiassistent.memory.*;
import org.junit.jupiter.api.Test;
import java.io.IOException;
import java.nio.*;
import java.nio.file.*;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

/** Source fixture is the independent full680-owner capture, not offsets generated by production. */
public class ClubFinancialCompetitionCaptureTest {
    static final ClubFinancialCompetitionLayout L=ClubFinancialCompetitionLayout.current();
    static final long BASE=ClubFinancialLoanCaptureTest.BASE,COMP_DESCRIPTOR=0x20000000,COMP_HEADER=0x20001000,COMP_TABLE=0x20010000;
    static List<String[]> csv(String name)throws Exception {
        byte[] bytes;try(var in=Files.newInputStream(Path.of("docs/reverse-engineering/fm26/evidence",name))){bytes=in.readNBytes(8*1024*1024+1);}
        assertThat(bytes.length).isLessThanOrEqualTo(8*1024*1024);return new String(bytes,java.nio.charset.StandardCharsets.US_ASCII).lines().skip(1).map(s->s.split(",",-1)).toList();
    }
    static List<String[]> vectors()throws Exception{return csv("financial_competition_vectors_population_fm620_20261026.csv");}
    static Map<Long,Long> keys()throws Exception {return keys("financial_competition_keys_population_fm620_20261026.csv");}
    static Map<Long,Long> keys(String name)throws Exception {
        var keys=new HashMap<Long,Long>();for(var k:csv(name))keys.put(hex(k[0]),Long.parseLong(k[2]));return keys;
    }
    static ClubUefaCoefficientCaptureTest.Blocks fixture()throws Exception {
        var f=ClubFinancialLedgerCaptureTest.fixture();
        for(var r:vectors()) {
            long finance=hex(r[4]),address=hex(r[10]);byte[] body=f.blocks.get(finance);
            System.arraycopy(HexFormat.of().parseHex(r[9]),0,body,Integer.parseInt(r[8],16),24);
            if(!r[11].isEmpty())f.put(address,HexFormat.of().parseHex(r[11]));
        }
        var table=ByteBuffer.allocate(8248*8).order(ByteOrder.LITTLE_ENDIAN);
        for(var k:csv("financial_competition_keys_population_fm620_20261026.csv")){long address=hex(k[0]);table.putLong(Integer.parseInt(k[1])*8,address);f.put(address,HexFormat.of().parseHex(k[3]));}
        f.put(BASE+0x4E49590,ClubFinancialLoanCaptureTest.longs(COMP_DESCRIPTOR));f.put(COMP_DESCRIPTOR+0x80,ClubFinancialLoanCaptureTest.longs(COMP_HEADER));
        f.put(COMP_HEADER,ClubFinancialLoanCaptureTest.longs(COMP_TABLE,COMP_TABLE+table.capacity(),COMP_TABLE+table.capacity()));f.put(COMP_TABLE,table.array());return f;
    }
    public static Map<Long,String> expectedPayloads()throws Exception {
        return expectedPayloads("financial_competition_vectors_population_fm620_20261026.csv","financial_competition_keys_population_fm620_20261026.csv");
    }
    public static Map<Long,String> expectedPayloads(String vectorFile,String keyFile)throws Exception {
        var keys=keys(keyFile);var byOwner=new LinkedHashMap<Long,List<String[]>>();
        for(var r:csv(vectorFile))byOwner.computeIfAbsent(Long.parseLong(r[1]),ignored->new ArrayList<>()).add(r);
        var out=new LinkedHashMap<Long,String>();for(var entry:byOwner.entrySet()) {
            var b=ByteBuffer.allocate(61480).order(ByteOrder.LITTLE_ENDIAN);var rows=entry.getValue();assertThat(rows).hasSize(10);
            for(int n=0;n<10;n++){var r=rows.get(n);assertThat(Integer.parseInt(r[6])*2+Integer.parseInt(r[7])).isEqualTo(n);
                var raw=ByteBuffer.wrap(HexFormat.of().parseHex(r[11])).order(ByteOrder.LITTLE_ENDIAN);b.putInt(raw.capacity()/16);
                for(int at=0;at<raw.capacity();at+=16){b.putInt(keys.get(raw.getLong(at)).intValue());b.putInt(raw.getInt(at+8));b.put(raw.array(),at+12,4);}}
            out.put(entry.getKey(),HexFormat.of().formatHex(Arrays.copyOf(b.array(),b.position())));
        }return out;
    }
    public static List<NativeClubSnapshot> capturedRecords()throws Exception{return capture(fixture()).records();}
    private static ClubIdentitySnapshot capture(ClubUefaCoefficientCaptureTest.Blocks f)throws Exception {
        return new ClubIdentitySnapshot(f,BASE,ClubIdentityLayout.current(),null,null,L.ledger(),L);
    }
    @Test void all680ProfilesAnd2747MembersKeepIdentitiesOrderAndUnassignedBytes()throws Exception {
        var f=fixture();var capture=capture(f);var expected=expectedPayloads();int owners=0,members=0;
        for(var r:capture.records()){assertThat(r.financialCompetitionsHex()).isEqualTo(expected.get(r.uniqueId()));if(r.financialCompetitionsHex()==null)continue;
            owners++;var profile=L.decode(HexFormat.of().parseHex(r.financialCompetitionsHex()),r.financialLedgerClock());
            members+=profile.periods().stream().mapToInt(p->p.tvRevenue().size()+p.prizeMoney().size()).sum();}
        assertThat(owners).isEqualTo(680);assertThat(members).isEqualTo(2747);capture.verify();
        var p=L.decode(HexFormat.of().parseHex(expected.get(1036L)),ClubFinancialLoanCaptureTest.CLOCK);
        assertThat(p.periods().getFirst().tvRevenue()).extracting(ClubFinancialCompetitionLayout.Member::competitionUid).containsExactly(29L,1301394L);
        assertThat(p.periods().getFirst().tvRevenue()).extracting(ClubFinancialCompetitionLayout.Member::amount).containsExactly(70047,62500);
        assertThat(p.periods().getFirst().prizeMoney()).extracting(ClubFinancialCompetitionLayout.Member::amount).containsExactly(12963102,6800000);
        assertThat(p.periods().getFirst().tvRevenue().getFirst().unassignedHex()).isEqualTo("b0010000");
        assertThat(p.periods().get(4).tvRevenue()).isEmpty();
    }
    @Test void everyShiftedComponentRejectsTheSameCapturedFixture()throws Exception {
        var f=fixture();var parts=ClubFinancialCompetitionLayout.class.getRecordComponents();var types=Arrays.stream(parts).map(java.lang.reflect.RecordComponent::getType).toArray(Class<?>[]::new);
        var constructor=ClubFinancialCompetitionLayout.class.getDeclaredConstructor(types);
        for(int i=0;i<parts.length;i++){Object[] args=new Object[parts.length];for(int j=0;j<args.length;j++)args[j]=parts[j].getAccessor().invoke(L);
            if(types[i]==long.class)args[i]=(Long)args[i]+1;else if(types[i]==int.class)args[i]=(Integer)args[i]+1;
            else {var v=L.ledger();args[i]=new ClubFinancialLedgerLayout(v.financeRel()+1,v.baseVtableRva(),v.fullVtableRva(),v.ownerRel(),v.fullBytes(),v.blocksRel(),v.blockStride(),v.blockCount(),v.recordRel(),v.recordBytes(),v.tailRel(),v.tailBytes(),v.slotCount(),v.slotBytes(),v.clockRva(),v.clockBytes());}
            var shifted=constructor.newInstance(args);
            assertThatThrownBy(()->new ClubIdentitySnapshot(f,BASE,ClubIdentityLayout.current(),null,null,L.ledger(),shifted)).as(parts[i].getName()).isInstanceOf(IOException.class).hasMessageContaining("layout anchor");}
    }
    @Test void publicationRejectsChangedRegistryIdentityHeaderPayloadAndClockAndCaptureRejectsWrongSum()throws Exception {
        var f=fixture();var capture=capture(f);var r=vectors().stream().filter(v->v[1].equals("1036")&&v[6].equals("0")&&v[7].equals("0")).findFirst().orElseThrow();
        long finance=hex(r[4]),payload=hex(r[10]),key=ByteBuffer.wrap(HexFormat.of().parseHex(r[11])).order(ByteOrder.LITTLE_ENDIAN).getLong();
        for(long address:new long[]{BASE+0x4E49590,COMP_HEADER,COMP_TABLE+20*8,key,finance+0x250,payload+12,BASE+L.ledger().clockRva()}) {
            var entry=f.blocks.floorEntry(address);byte[] old=entry.getValue(),changed=old.clone();changed[Math.toIntExact(address-entry.getKey())]^=1;f.put(entry.getKey(),changed);
            assertThatThrownBy(capture::verify).isInstanceOf(IOException.class).hasMessageContaining("changed");f.put(entry.getKey(),old);
        }capture.verify();
        byte[] old=f.blocks.get(payload),changed=old.clone();changed[8]^=1;f.put(payload,changed);
        assertThatThrownBy(()->capture(f)).isInstanceOf(IOException.class).hasMessageContaining("scalar reconciliation");
    }
    static long hex(String s){return Long.parseUnsignedLong(s,16);}
}
